// formatNumber formats a non-negative cent amount with the given
// thousands and decimal separators, e.g. 123456 -> "1,234.56".
func formatNumber(cents int, thousandsSep, decimalSep string) string {
	dollars := cents / 100
	remainder := cents % 100

	var grouped strings.Builder
	s := strconv.Itoa(dollars)
	for i := 0; i < len(s); i += 3 {
		if i > 0 {
			grouped.WriteString(thousandsSep)
		}
		grouped.WriteString(s[i:])
	}
	return grouped.String() + decimalSep + fmt.Sprintf("%02d", remainder)
}
